from pathlib import Path
import csv,json,hashlib
p=Path('.');out=p/'agents/reviewer_15'
frames=list(csv.DictReader((p/'tables/k_rep_frames_batch03.csv').open()))
fields=list(csv.DictReader((p/'agents/reviewer_13/art_audit_batch02a.csv').open()).fieldnames)
base_limit='Sparse native representatives only; intermediate motion, onset/settle timing, easing, source layers/software, exact font and asset origin UNAVAILABLE. ASR_UNCERTIFIED; no actual listening.'
rows=[]
def add(state,assets,pose,layers,layout,palette,typography,style,camera,events,changes,extra='',confidence='medium'):
 fs=[r for r in frames if r['state_v5']==state]
 rows.append(dict(zip(fields,[state,'; '.join(r['native_png'] for r in fs),assets,pose,layers,layout,palette,typography,style,camera,events,changes,base_limit+' '+extra,'OBSERVED samples; camera/intent where stated INFERRED; supplied palette clusters MEASURED by prior extraction',confidence])))
